// Secure version with common security hardening
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet'); // Security headers
const cors = require('cors');
const xss = require('xss-clean'); // XSS prevention
const mongoSanitize = require('express-mongo-sanitize'); // NoSQL injection prevention

const app = express();

// Security middleware stack
app.use(helmet()); // Sets various HTTP security headers
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true
}));
app.use(express.json({ limit: '10kb' })); // Set reasonable JSON size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(xss()); // Sanitize user data to prevent XSS
app.use(mongoSanitize()); // Prevent MongoDB injection

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/api/', limiter);

// Health check - typically public
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    timestampMonotonic: process.hrtime.bigint()
  });
});

// User endpoint - requires authentication (example)
app.get('/users', (req, res) => {
  // In production, this should check:
  // 1. User is authenticated (JWT, session, etc.)
  // 2. User has appropriate permissions
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }
    // Never return sensitive data
  ]);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler - sanitize error responses
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

