// Configuration Hardened application with environment variables
const express = require('express');

// Validate required environment variables at startup
function validateEnv() {
  const required = ['PORT', 'ENVIRONMENT'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  return process.env.ENVIRONMENT;
}

const app = express();
const PORT = process.env.PORT || 3000;
const ENV = validateEnv();

// Load configurable test data from environment
// Format: USER_DATA=user-id:Name:email:user-id:Name:email (colon-separated)
const getDataFromEnv = () => {
  const userData = process.env.USER_DATA;
  return userData
    ? userData.split('|').map(item => {
        const [id, name, email] = item.split(':');
        return { id: Number(id), name, email };
      })
    : getSafeDefaultData();
};

// Anonymized, safe default data (never commit real user data)
function getSafeDefaultData() {
  return [
    { id: 1001, name: 'Test User Alpha', email: 'test.user.1@anon.example.com' },
    { id: 1002, name: 'Test User Beta', email: 'test.user.2@anon.example.com' },
  ];
}

// CORS origin validation
const corsOrigin = process.env.CORS_ORIGIN || 'http://localhost:3000';
app.use(cors({
  origin: origin => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [corsOrigin];

    if (!origin || allowedOrigins.some(allowed => origin.includes(allowed) || allowed.includes('*'))) {
      return true;
    }

    console.warn(`Blocked CORS request from ${origin}`);
    return false;
  },
  credentials: true
}));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    env: ENV,
    port: PORT,
    uptime: process.uptime()
  });
});

// Users endpoint - uses configurable test data
app.get('/users', (req, res) => {
  const users = getDataFromEnv();

  if (process.env.SANITIZE_USER_DATA === 'true') {
    // Remove sensitive fields before returning
    res.json(users.map(({ id, name }) => ({ id, name })));
  } else {
    res.json(users);
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found', path: req.path });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? undefined : err.message
  });
});

// Graceful shutdown
const server = app.listen(PORT, () => {
  console.log(`[${ENV}] Server running on port ${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

